<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Platform/manage')}">平台分类列表</a>|					<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Platform/add',array('fid'=>$area['id'],'province_id'=>$area['province_id'],'city_id'=>$area['city_id']))}','添加子分类',800,560,true,false,false,addbtn,'add',true);">添加子分类</a>					<a href="{pigcms{:U('Platform/classfiy',array('id'=>$_GET['id']))}" class="on">子分类列表</a>|				</ul>			</div>				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>排序</th>								<th>所属区域</th>								<th>分类名称</th>								<th>状态</th>								<th>添加时间</th>								<th>开启/关闭</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.sort}</td>										<td>{pigcms{$vo.province_name}{pigcms{$vo.city_name}</td>										<td>{pigcms{$vo.cate_name}</td>										<td>											<if condition="$vo['status'] eq 0">													开启											<else/>													关闭											</if>											</td>										<td><if condition="$vo['add_time']">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<else/>无</if></td>										<td>											<span class="cb-enable"><label class="cb-enable <if condition="$vo['status'] eq 0">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.id}', 0)" >开启</span><input type="radio" value="0" <if condition="$vo['status'] eq 0">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['status'] eq 1">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.id}', 1)">关闭</span><input type="radio" value="1" <if condition="$vo['status'] eq 1">checked="checked"</if> /></label></span>										</td>										<td>										<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Platform/edit',array('id'=>$vo['id'],'is_classfiy'=>'true'))}','编辑商家信息',800,560,true,false,false,editbtn,'edit',true);">编辑</a> | 																				<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Platform/del_cate')}">删除</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>				</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Merchant/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><script>            var lockInfo = false;            function del_category(topic_cate_id){                if (lockInfo) return;                lockInfo = true;                var del_category = "{pigcms{:U('Community/del_topic_cate')}";                $.post(del_category,{'topic_cate_id':topic_cate_id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }            function discoverSwitch(id, status) {            	console.log(id);                if (lockInfo) return;                lockInfo = true;                var url = '';                var close_category = "{pigcms{:U('Platform/close_cate')}";                var open_category = "{pigcms{:U('Platform/open_cate')}";                if (0 == status) {                    url = open_category;                } else if(1 == status) {                    url = close_category;                } else {                    return;                }                $.post(url,{'id': id,'is_second':true},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }        </script><include file="Public:footer"/>